:root {
  --r-sm: 10px;    /* поля ввода, чипы */
  --r-md: 16px;    /* карточки */
  --r-lg: 22px;    /* панели и модальные окна */
  --r-pill: 999px; /* кнопки и бейджи */

  /* широкий мягкий слой держит объём, узкий резкий — контакт с поверхностью */
  --shadow-sm: 0 2px 10px rgba(0, 0, 0, .28);
  --shadow-md: 0 12px 34px rgba(0, 0, 0, .42);
  --shadow-lg: 0 26px 70px rgba(0, 0, 0, .55);
  --inner-hi: inset 0 1px 0 rgba(255, 255, 255, .07);
}

.card { border-radius: var(--r-md); box-shadow: var(--shadow-md), var(--inner-hi); }
.cta  { border-radius: var(--r-pill); box-shadow: var(--shadow-sm), var(--inner-hi); }

